steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        issue(identifier: \"MOB-3\") {
          id
          identifier
          title
          team { id name }
        }
        issueLabels(name: \"Regression\") {
          id
          name
          group {
            id
            name
          }
        }
      }
    "
  }'
